class _AssistantPageState extends State<AssistantPage> {
 final prompt=TextEditingController(); final base=TextEditingController(text:'http://localhost:3001/v1'); final key=TextEditingController(); final model=TextEditingController(text:'auto');
 String? result,error; bool busy=false;
 @override void dispose(){prompt.dispose();base.dispose();key.dispose();model.dispose();super.dispose();}
 Future<void> send() async { final q=prompt.text.trim(); if(q.isEmpty||busy)return; final b=base.text.trim().replaceAll(RegExp(r'/+$'),''); if(!b.startsWith('http://')&&!b.startsWith('https://')){setState(()=>error='URL API invalide');return;} setState(()=>busy=true); error=null; result=null; prompt.clear(); try { final r=await http.post(Uri.parse('$b/chat/completions'),headers:{'Content-Type':'application/json',if(key.text.trim().isNotEmpty)'Authorization':'Bearer ${key.text.trim()}'},body:jsonEncode({'model':model.text.trim().isEmpty?'auto':model.text.trim(),'messages':[{'role':'system','content':'Tu es l’assistant MEDIZY en Algérie. Réponds en français clair et prudent. Ne diagnostique pas, ne prescris pas et conseille les urgences en cas de danger immédiat. Ne demande pas de données personnelles.'},{'role':'user','content':q}]})).timeout(const Duration(seconds:60)); if(r.statusCode<200||r.statusCode>=300)throw Exception('HTTP ${r.statusCode}: ${r.body.length>300?r.body.substring(0,300):r.body}'); final j=jsonDecode(r.body) as Map<String,dynamic>; final choices=j['choices'] as List?; final a=choices?.isNotEmpty==true?choices!.first['message']?['content']?.toString():null; if(a==null||a.trim().isEmpty)throw Exception('Réponse vide'); setState(()=>result=a.trim()); }catch(e){setState(()=>error='Connexion impossible : $e. Vérifie que FreeLLMAPI est démarré et que l’URL est accessible depuis le téléphone.');}finally{if(mounted)setState(()=>busy=false);} }
 @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Row(children:[Icon(Icons.auto_awesome,color:Color(0xff159c98),size:28),SizedBox(width:10),Text('Assistant MEDIZY',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold))]),const Text('Connexion à FreeLLMAPI • API compatible OpenAI'),const SizedBox(height:12),ExpansionTile(title:const Text('Paramètres de connexion'),childrenPadding:const EdgeInsets.all(12),children:[TextField(controller:base,decoration:const InputDecoration(labelText:'URL API',hintText:'http://localhost:3001/v1')),TextField(controller:key,obscureText:true,decoration:const InputDecoration(labelText:'Clé API unifiée')),TextField(controller:model,decoration:const InputDecoration(labelText:'Modèle',hintText:'auto')),const Text('La clé reste en mémoire uniquement durant cette session.',style:TextStyle(fontSize:12,color:Colors.grey))]),const SizedBox(height:12),TextField(controller:prompt,minLines:2,maxLines:5,decoration:InputDecoration(hintText:'Pose ta question…',border:OutlineInputBorder(borderRadius:BorderRadius.circular(14)))),const SizedBox(height:8),FilledButton.icon(onPressed:busy?null:send,icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.send),label:Text(busy?'Connexion…':'Envoyer')),if(error!=null)Card(color:Colors.orange.withOpacity(.12),child:Padding(padding:const EdgeInsets.all(12),child:Text(error!))),if(result!=null)Card(child:Padding(padding:const EdgeInsets.all(14),child:Text(result!))),const SizedBox(height:16),const Text('Attention : l’assistant ne remplace pas un médecin. Ne saisis pas de nom, téléphone, dossier ou donnée médicale identifiable. En urgence, contacte les services d’urgence.',style:TextStyle(fontSize:12,color:Colors.grey))]); }
